# Community Windows 12-inspired desktop overlay installer
import base64,ctypes,json,os,subprocess,sys,winreg
from pathlib import Path
ROOT=Path(os.environ.get("PROGRAMDATA",r"C:\ProgramData"))/"Windows12"
PAYLOAD=""
def elevated():
 try:return bool(ctypes.windll.shell32.IsUserAnAdmin())
 except:return False
def relaunch():
 r=ctypes.windll.shell32.ShellExecuteW(None,"runas",sys.executable,subprocess.list2cmdline(sys.argv),None,1)
 if r<=32:raise SystemExit("Administrator approval was not granted")
 raise SystemExit
def install(accent,gradient,startup):
 ROOT.mkdir(parents=True,exist_ok=True)
 venv=ROOT/".venv"
 subprocess.check_call([sys.executable,"-m","venv",str(venv)])
 vpy=venv/"Scripts"/"python.exe"
 subprocess.check_call([str(vpy),"-m","ensurepip","--upgrade"])
 subprocess.check_call([str(vpy),"-m","pip","install","--upgrade","pip"])
 subprocess.check_call([str(vpy),"-m","pip","install","PyQt6","pyinstaller"])
 src=ROOT/"Windows12.py";src.write_bytes(base64.b64decode(PAYLOAD))
 (ROOT/"config.json").write_text(json.dumps({"accent":accent,"gradient":gradient,"weather_lat":29.4241,"weather_lon":-98.4936},indent=2))
 data=Path(os.environ.get("LOCALAPPDATA",str(Path.home()/"AppData"/"Local")))/"Windows12";data.mkdir(parents=True,exist_ok=True)
 if not (data/"widgets.json").exists():(data/"widgets.json").write_text("[]")
 if not (data/"TaskbarPos.json").exists():(data/"TaskbarPos.json").write_text('{"x":580,"y":930}')
 # Stop an installed copy before rebuilding. Windows locks running EXE files.
 subprocess.run(["taskkill","/F","/T","/IM","Windows12.exe"],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,check=False)
 import shutil,tempfile,time
 time.sleep(1)
 stage=Path(tempfile.mkdtemp(prefix="Windows12-build-"))
 try:
  subprocess.check_call([str(vpy),"-m","PyInstaller","--noconfirm","--clean","--windowed","--onefile","--noupx","--name","Windows12.new","--distpath",str(stage/"dist"),"--workpath",str(stage/"build"),"--specpath",str(stage),str(src)])
  built=stage/"dist"/"Windows12.new.exe";exe=ROOT/"Windows12.exe"
  if not built.exists():raise FileNotFoundError(f"PyInstaller did not create {built}")
  for attempt in range(10):
   try:
    if exe.exists():exe.unlink()
    shutil.copy2(built,exe)
    break
   except PermissionError:
    if attempt==9:raise
    time.sleep(.5)
 finally:
  shutil.rmtree(stage,ignore_errors=True)
 (ROOT/"OnStart.cmd").write_text('@echo off\nstart "" "%ProgramData%\\Windows12\\Windows12.exe" --boot\n')
 (ROOT/"WidgetStudio.cmd").write_text('@echo off\nstart "" "%ProgramData%\\Windows12\\Windows12.exe" --CreateWidgetPanel\n')
 (ROOT/"Uninstall.cmd").write_text('@echo off\nreg delete "HKLM\\Software\\Microsoft\\Windows\\CurrentVersion\\Run" /v Windows12Theme /f\ntaskkill /im Windows12.exe /f >nul 2>&1\necho Delete %ProgramData%\\Windows12 when ready.\npause\n')
 if startup:
  with winreg.CreateKeyEx(winreg.HKEY_LOCAL_MACHINE,r"Software\Microsoft\Windows\CurrentVersion\Run",0,winreg.KEY_SET_VALUE|winreg.KEY_WOW64_64KEY) as k:winreg.SetValueEx(k,"Windows12Theme",0,winreg.REG_SZ,f'"{exe}" --boot')

def gui():
 import tkinter as tk
 from tkinter import messagebox
 w=tk.Tk();w.title("Windows 12 Theme Installer");w.geometry("560x360");w.resizable(False,False)
 tk.Label(w,text="Windows 12-inspired Desktop Theme",font=("Segoe UI",20,"bold")).pack(pady=(22,8))
 tk.Label(w,text="Dependencies are installed into a private virtual environment, not into your main Python installation.",wraplength=500).pack(pady=8)
 f=tk.Frame(w);f.pack(fill="x",padx=35,pady=10)
 tk.Label(f,text="Accent").grid(row=0,column=0,sticky="w");aa=tk.Entry(f);aa.insert(0,"#8b5cf6");aa.grid(row=0,column=1,sticky="ew")
 tk.Label(f,text="Gradient").grid(row=1,column=0,sticky="w");gg=tk.Entry(f);gg.insert(0,"#4c1d95,#a855f7");gg.grid(row=1,column=1,sticky="ew");f.columnconfigure(1,weight=1)
 sv=tk.BooleanVar(value=True);tk.Checkbutton(w,text="Start at Windows sign-in",variable=sv).pack();status=tk.Label(w,text="Ready");status.pack(pady=5)
 def go():
  btn.config(state="disabled");status.config(text=r"Installing into C:\ProgramData\Windows12\.venv ...");w.update()
  try:install(aa.get().strip(),gg.get().strip(),sv.get());messagebox.showinfo("Done",f"Installed to {ROOT}");status.config(text="Installed")
  except Exception as e:messagebox.showerror("Failed",str(e));status.config(text="Installation failed")
  btn.config(state="normal")
 btn=tk.Button(w,text="Install",command=go,width=24);btn.pack(pady=10);w.mainloop()

if __name__=="__main__":
 if os.name!="nt":raise SystemExit("Run this installer on Windows")
 if not elevated():relaunch()
 gui()
